import os
import json
from composio import ComposioToolSet, Action

def main():
    with open('/logs/trial_id', 'r') as f:
        trial_id = f.read().strip()

    repo_name = f"issue-test-{trial_id}"
    owner = "zealt-user01"

    print(f"Working on repo {owner}/{repo_name}")

    toolset = ComposioToolSet(entity_id=owner)

    # List issues
    try:
        list_response = toolset.execute_action(
            action=Action.GITHUB_ISSUES_LIST_FOR_REPO,
            params={
                "owner": owner,
                "repo": repo_name,
                "labels": "bug"
            }
        )
        print("List response:", json.dumps(list_response, indent=2))

        issues = []
        if isinstance(list_response, dict):
            if "data" in list_response:
                issues = list_response["data"]
            elif "response_data" in list_response:
                issues = list_response["response_data"]
            else:
                issues = [list_response]
        elif isinstance(list_response, list):
            issues = list_response

        print(f"Found {len(issues)} issues")

        for issue in issues:
            issue_number = issue.get("number") if isinstance(issue, dict) else None
            if issue_number:
                print(f"Commenting on issue {issue_number}")
                comment_response = toolset.execute_action(
                    action=Action.GITHUB_ISSUES_CREATE_COMMENT,
                    params={
                        "owner": owner,
                        "repo": repo_name,
                        "issue_number": issue_number,
                        "body": f"Fixed in trial {trial_id}"
                    }
                )
                print(f"Comment response:", json.dumps(comment_response, indent=2))
    except Exception as e:
        print(f"Error: {e}")

if __name__ == "__main__":
    main()

